import React, { useState } from "react";
import { useNavigate, useLocation } from "react-router-dom";

const PRIMARY = "#EA580C";
const PRIMARY_LIGHT = "#FFF4EE";

export type NavItem = {
  id: string;
  label: string;
  path: string;
  icon?: string;
};

export type NavGroup = {
  id: string;
  label: string;
  path: string;
  icon?: string;
  children?: NavItem[];
};

interface SidebarProps {
  features: NavGroup[];
  collapsed?: boolean;
  onToggle?: () => void;
  onNavigate?: (item: NavItem) => void;
  isMobile?: boolean;
  mobileOpen?: boolean;
}

export const Sidebar: React.FC<SidebarProps> = ({
  features,
  collapsed = false,
  onToggle,
  onNavigate,
  isMobile = false,
  mobileOpen = false,
}) => {
  const navigate = useNavigate();
  const location = useLocation();
  const [openGroups, setOpenGroups] = useState<Record<string, boolean>>({
    users: true,
  });

  const width = collapsed ? 64 : 280;

  const sidebarStyle: React.CSSProperties = isMobile
    ? {
        position: "fixed",
        top: 0,
        left: 0,
        height: "100vh",
        width: 280,
        background: "#fff",
        borderRight: "1px solid #E2E8F0",
        display: "flex",
        flexDirection: "column",
        zIndex: 150,
        transform: mobileOpen ? "translateX(0)" : "translateX(-100%)",
        transition: "transform 0.25s ease",
        boxShadow: mobileOpen ? "4px 0 24px rgba(0,0,0,0.12)" : "none",
      }
    : {
        width,
        minWidth: width,
        height: "100vh",
        background: "#F8FAFC",
        borderRight: "1px solid #E2E8F0",
        display: "flex",
        flexDirection: "column",
        transition: "all 0.25s ease",
        overflow: "hidden",
        position: "fixed",
        left: 0,
        top: 0,
        zIndex: 100,
        boxSizing: "border-box",
      };

  const handleClick = (item: NavItem) => {
    navigate(item.path);
    onNavigate?.(item);
  };

  const toggleGroup = (groupId: string) => {
    setOpenGroups((prev) => ({ ...prev, [groupId]: !prev[groupId] }));
  };

  const isPathActive = (path: string) =>
    location.pathname === path || location.pathname.startsWith(`${path}/`);

  return (
    <aside style={sidebarStyle}>
      {/* HEADER */}
      <div
        style={{
          height: 64,
          minHeight: 64,
          padding: collapsed && !isMobile ? "10px 0" : "10px 16px",
          display: "flex",
          alignItems: "center",
          justifyContent: collapsed && !isMobile ? "center" : "flex-start",
          borderBottom: "1px solid #E2E8F0",
          boxSizing: "border-box",
        }}
      >
        <button
          onClick={onToggle}
          aria-label="Toggle sidebar"
          style={{
            border: "none",
            background: "transparent",
            cursor: "pointer",
            padding: 0,
            width: "100%",
            display: "flex",
            alignItems: "center",
            gap: 10,
            justifyContent: collapsed && !isMobile ? "center" : "flex-start",
          }}
        >
          <div
            style={{
              width: 36,
              height: 36,
              borderRadius: 10,
              background: PRIMARY,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              flexShrink: 0,
            }}
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
              <path
                d="M13 2L4.09 12.11a1 1 0 00-.09 1.13L9 21l4-7h6l-6-12z"
                fill="#fff"
              />
            </svg>
          </div>
          {(!collapsed || isMobile) && (
            <span
              style={{
                fontWeight: 700,
                fontSize: 15,
                color: "#0F172A",
                letterSpacing: "0.05em",
                whiteSpace: "nowrap",
              }}
            >
              WEERA
            </span>
          )}
        </button>
      </div>

      {/* NAV */}
      <nav
        style={{
          flex: 1,
          overflowY: "auto",
          overflowX: "hidden",
          padding: "12px 8px",
        }}
      >
        <ul style={{ listStyle: "none", padding: 0, margin: 0, display: "flex", flexDirection: "column", gap: 2 }}>
          {features.map((group) => {
            const groupActive = isPathActive(group.path);
            const hasChildren = !!group.children?.length;
            const isOpen = openGroups[group.id];
            const showLabel = !collapsed || isMobile;

            return (
              <React.Fragment key={group.id}>
                <li>
                  <button
                    onClick={() => {
                      if (hasChildren && showLabel) {
                        toggleGroup(group.id);
                      } else {
                        handleClick({ id: group.id, label: group.label, path: group.path, icon: group.icon });
                      }
                    }}
                    title={!showLabel ? group.label : undefined}
                    style={{
                      width: "100%",
                      height: 44,
                      border: "none",
                      borderRadius: 10,
                      cursor: "pointer",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: showLabel ? "flex-start" : "center",
                      gap: 12,
                      padding: showLabel ? "0 12px" : "0",
                      background: groupActive ? PRIMARY_LIGHT : "transparent",
                      color: groupActive ? PRIMARY : "#475569",
                      fontWeight: groupActive ? 600 : 500,
                      fontSize: 13.5,
                      transition: "all 0.15s ease",
                    }}
                  >
                    <span style={{ fontSize: 18, flexShrink: 0, lineHeight: 1 }}>{group.icon}</span>
                    {showLabel && (
                      <>
                        <span style={{ flex: 1, textAlign: "left", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                          {group.label}
                        </span>
                        {hasChildren && (
                          <span
                            style={{
                              fontSize: 11,
                              opacity: 0.6,
                              transition: "transform 0.2s",
                              transform: isOpen ? "rotate(90deg)" : "rotate(0deg)",
                              display: "inline-block",
                            }}
                          >
                            ›
                          </span>
                        )}
                      </>
                    )}
                  </button>
                </li>

                {showLabel && hasChildren && isOpen && group.children?.map((child) => {
                  const childActive = isPathActive(child.path);
                  return (
                    <li key={child.id} style={{ paddingLeft: 16 }}>
                      <button
                        onClick={() => handleClick(child)}
                        style={{
                          width: "100%",
                          height: 38,
                          border: "none",
                          borderRadius: 8,
                          cursor: "pointer",
                          display: "flex",
                          alignItems: "center",
                          gap: 10,
                          padding: "0 12px",
                          background: childActive ? PRIMARY_LIGHT : "transparent",
                          color: childActive ? PRIMARY : "#64748B",
                          fontWeight: childActive ? 500 : 400,
                          fontSize: 13,
                          transition: "all 0.15s ease",
                        }}
                      >
                        {child.icon && <span style={{ fontSize: 15 }}>{child.icon}</span>}
                        <span>{child.label}</span>
                      </button>
                    </li>
                  );
                })}
              </React.Fragment>
            );
          })}
        </ul>
      </nav>
    </aside>
  );
};

export default Sidebar;
